import {categories} from './data.mjs';
export const money=amount=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2,minimumFractionDigits:0}).format(amount);
export function validate(request){const errors=[];const cat=categories[request.category];if(!cat)return ['Choose a supported category.'];const q=Number(request.quantity);if(!Number.isSafeInteger(q)||q<1||q>10000)errors.push('Quantity must be a whole number from 1 to 10,000.');if(!['Cebu City','Mandaue City'].includes(request.location))errors.push('Choose a supported location.');if(!/^\d{4}-\d{2}-\d{2}$/.test(request.date||''))errors.push('Choose the date you need the service.');if(request.budget!==''&&request.budget!=null&&(!Number.isFinite(Number(request.budget))||Number(request.budget)<=0))errors.push('Budget must be positive, or leave it blank.');for(const [key,label,options]of cat.fields)if(!options.includes(request.specs?.[key]))errors.push('Choose '+label.toLowerCase()+'.');return errors;}
export function estimate(s,request){const q=Number(request.quantity);let unit=Number(s.rate);if(s.category==='printing'){for(const tier of [...(s.tiers||[])].sort((a,b)=>a.min-b.min))if(q>=tier.min)unit=tier.rate;}const lines=[{label:s.category==='printing'?'Shirts':categories[s.category].name+' service',quantity:q,unit,amount:q*unit}];if(s.category==='printing'){const pr=s.printRates?.[request.specs.size];if(!Number.isFinite(pr))throw new Error('Print rate missing');lines.push({label:request.specs.size+' front print',quantity:q,unit:pr,amount:q*pr});}if(s.category==='photography'&&request.specs.coverage==='Photo + video'){const v=s.videoRate||0;lines.push({label:'Video coverage',quantity:q,unit:v,amount:q*v});}if(s.fee)lines.push({label:'Delivery / service fee',quantity:1,unit:s.fee,amount:s.fee});const totalCents=lines.reduce((a,l)=>a+Math.round(l.amount*100),0);if(!Number.isSafeInteger(totalCents)||totalCents<0)throw new Error('Invalid pricing');return {lines,total:totalCents/100,deposit:s.deposit||0};}
export function matchSuppliers(request,suppliers){if(validate(request).length)return {matches:[],excluded:[]};const matches=[],excluded=[];for(const s of suppliers.filter(s=>s.category===request.category)){const reasons=[];if(!s.active)reasons.push('Not accepting requests');if(!s.areas.includes(request.location))reasons.push('Outside service area');if(Number(request.quantity)>s.capacity)reasons.push('Exceeds listed capacity');for(const [key,label]of categories[request.category].fields)if(!s.options[key]?.includes(request.specs[key]))reasons.push(label+': '+request.specs[key]+' not offered');let price;try{price=estimate(s,request);}catch{reasons.push('Pricing needs confirmation');}if(price&&request.budget!==''&&request.budget!=null&&price.total>Number(request.budget))reasons.push('Above budget cap');if(reasons.length)excluded.push({supplier:s,reasons});else matches.push({supplier:s,...price});}matches.sort((a,b)=>a.total-b.total);return {matches,excluded};}
// Transparent local helper, not an AI model. It only extracts supported patterns.
export function parseLocally(text,category){const out={specs:{},unresolved:[]};const t=text.toLowerCase();let m;if(category==='catering'){m=t.match(/\b(\d+)\s*(?:packed\s*)?(?:lunches|meals|people|pax)/);if(m)out.quantity=+m[1];if(/vegetarian/.test(t))out.specs.diet='Vegetarian options';if(/buffet/.test(t))out.specs.format='Buffet';else if(/packed/.test(t))out.specs.format='Packed lunch';}if(category==='printing'){m=t.match(/\b(\d+)\s*(?:black\s*)?(?:(?:100%\s*)?cotton\s*)?(?:shirts|t-shirts)/);if(m)out.quantity=+m[1];if(/100\s*%\s*cotton/.test(t))out.specs.material='100% cotton';else if(/cotton blend/.test(t))out.specs.material='Cotton blend';else if(/polyester/.test(t))out.specs.material='Polyester';if(/\ba4\b/.test(t))out.specs.size='A4';if(/\ba5\b/.test(t))out.specs.size='A5';if(/\bdtf\b/.test(t))out.specs.method='DTF';if(/screen print/.test(t))out.specs.method='Screen print';}if(category==='equipment'){m=t.match(/\b(\d+)\s*days?/);if(m)out.quantity=+m[1];else if(/one.day/.test(t))out.quantity=1;if(/espresso/.test(t)&&/grinder/.test(t))out.specs.equipment='Espresso machine + grinder';if(/projector/.test(t))out.specs.equipment='Projector + screen';if(/self.setup/.test(t))out.specs.setup='Self setup';else if(/setup/.test(t))out.specs.setup='Setup included';}if(category==='photography'){m=t.match(/\b(\d+)[ -]*hours?/);if(m)out.quantity=+m[1];else if(/four.hour/.test(t))out.quantity=4;if(/video/.test(t))out.specs.coverage='Photo + video';else if(/photo/.test(t))out.specs.coverage='Photography';if(/\b7 days|one week/.test(t))out.specs.turnaround='7 days';if(/\b14 days|two weeks/.test(t))out.specs.turnaround='14 days';}if(/mandaue/.test(t))out.location='Mandaue City';else if(/cebu|lahug/.test(t))out.location='Cebu City';m=t.match(/(?:budget(?:\s*(?:is|of|:))?\s*(?:₱|php|p)?\s*)([\d,]+)/);if(m)out.budget=Number(m[1].replaceAll(',',''));return out;}
export function validateOffer(total,expiry,today=new Date().toISOString().slice(0,10)){if(!Number.isFinite(Number(total))||Number(total)<=0)return 'Enter a positive final total.';if(!expiry||expiry<today)return 'Choose an expiry date today or later.';return '';}
export function canAccept(offer,today=new Date().toISOString().slice(0,10)){return !!offer&&offer.status==='Quoted'&&offer.expires>=today;}
